<template>
  <main class="archive-page">
    <header class="archive-header"><router-link :to="directoryTo" aria-label="返回赛事档案目录">‹</router-link><span>年度赛事档案</span><router-link :to="directoryTo" class="archive-header-directory">目录</router-link></header>
    <div v-if="error" class="archive-state" role="alert"><p>{{ error }}</p><button type="button" class="archive-secondary" @click="load">重新加载</button><router-link class="archive-text-link" :to="directoryTo">返回赛事目录</router-link></div>
    <p v-else-if="loading" class="archive-state" role="status">正在加载年度档案…</p>
    <template v-else-if="race && archive">
      <section class="archive-intro"><span class="archive-kicker">{{ race.city }} · {{ race.shortName }}</span><h1>{{ race.name }}</h1><p>{{ race.tagline }}</p><div class="archive-badges"><span>世界田联 {{ certification(race.worldAthletics) }}</span><span>中国田协 {{ certification(race.caa) }}</span></div></section>
      <div class="archive-edition-bar"><label>年度档案<select v-model="year" aria-label="选择档案年份" @change="chooseYear"><option v-for="y in years" :key="y" :value="y">{{ y }} 年</option></select></label><span>{{ edition?.date || '比赛日期待核验' }}</span></div>
      <nav class="archive-tabs" aria-label="档案栏目"><button v-for="t in tabs" :key="t.id" type="button" :class="{selected:tab===t.id}" :aria-pressed="tab===t.id" @click="chooseTab(t.id)">{{ t.label }}</button></nav>
      <div class="archive-body archive-detail-body">
        <router-link v-if="fromRace" class="archive-return" :to="'/races/'+fromRace.id"><span><small>你正在了解这场报名赛事</small><strong>{{ fromRace.name }}</strong></span><span aria-hidden="true">›</span></router-link>
        <p v-if="!edition" class="archive-state">该年度资料尚未收录。</p>
        <template v-else>
          <template v-if="tab==='overview'"><section class="archive-panel"><h2>关于这场比赛</h2><p class="archive-prose">{{ archive.intro || race.summary || race.tagline }}</p><dl class="archive-facts"><div><dt>档案年份</dt><dd>{{ year }} 年</dd></div><div><dt>比赛日期</dt><dd>{{ edition.date || '待核验' }}</dd></div><div><dt>比赛项目</dt><dd>{{ edition.distance || '待核验' }}</dd></div></dl></section><section v-if="archive.highlights?.length" class="archive-panel"><h2>跑之前，先了解</h2><div v-for="h in archive.highlights" :key="h.title" class="archive-editorial"><h3>{{ h.title }}</h3><p>{{ h.body }}</p></div></section><section v-if="edition.notes?.length" class="archive-panel"><h2>{{ year }} 年资料说明</h2><p v-for="note in edition.notes" :key="note" class="archive-prose">{{ note }}</p></section></template>
          <template v-if="tab==='route'"><section class="archive-panel"><div class="archive-section-heading"><h2>{{ year }} 年赛道</h2><span>本届路线</span></div><p class="archive-prose">{{ edition.route?.summary || '本届路线尚无已核验资料，取得本届可靠资料后补充。' }}</p><dl class="archive-facts"><div><dt>起点</dt><dd>{{ edition.route?.start || '待核验' }}</dd></div><div><dt>终点</dt><dd>{{ edition.route?.finish || '待核验' }}</dd></div></dl><a v-if="safeUrl(edition.route?.mapUrl) && !failedImage('route')" class="archive-map-link" :href="edition.route.mapUrl" target="_blank" rel="noopener noreferrer"><img :src="edition.route.mapUrl" :alt="year+'年'+race.name+'官方路线图'" @error="markImageFailed('route')" /><span>打开路线图查看大图 ↗</span></a><p v-else class="archive-caption">{{ failedImage('route') ? '路线图暂时无法显示，可查看官方原文。' : '尚未收录本届官方路线图。' }}</p><a v-if="safeUrl(edition.route?.mapSourceUrl)" class="archive-external" :href="edition.route.mapSourceUrl" target="_blank" rel="noopener noreferrer">查看路线官方原文 ↗</a></section><section v-if="edition.route?.changes || edition.route?.analysis?.length" class="archive-panel"><h2>路线变化与跑法参考</h2><p v-if="edition.route.changes" class="archive-prose">{{ edition.route.changes }}</p><p v-for="(line,i) in edition.route.analysis||[]" :key="i" class="archive-prose">{{ line }}</p><p class="archive-caption">路线分析为编辑参考；交通与赛道安排以本届组委会公告为准。</p></section></template>
          <template v-if="tab==='registration'"><section class="archive-panel"><h2>{{ year }} 年报名与中签</h2><p class="archive-prose">{{ edition.registration?.method || '报名方式待核验' }}</p><dl class="archive-facts"><div v-for="f in registrationFacts" :key="f.label"><dt>{{ f.label }}</dt><dd>{{ f.value }}</dd></div></dl><p v-if="edition.registration?.lotteryNote" class="archive-callout">{{ edition.registration.lotteryNote }}</p><p v-if="edition.registration?.note" class="archive-prose">{{ edition.registration.note }}</p></section><section class="archive-panel"><h2>历年中签情况</h2><p class="archive-caption">报名人数、抽签池与参赛规模口径不同。缺失数据不参与推算，中签率仅展示已核验公布值。</p><div class="archive-table-scroll" tabindex="0" role="region" aria-label="历年报名中签表，可横向滚动"><table class="archive-table"><thead><tr><th>年份</th><th>报名人数</th><th>有效报名</th><th>抽签人数</th><th>抽签名额</th><th>直通名额</th><th>公布中签率</th></tr></thead><tbody><tr v-for="e in editions" :key="e.year" :class="{current:String(e.year)===year}"><th><button type="button" @click="setYear(String(e.year))">{{ e.year }}</button></th><td>{{ e.registration?.applicants || '未收录' }}</td><td>{{ e.registration?.eligibleApplicants || '未收录' }}</td><td>{{ e.registration?.lotteryPool || '未收录' }}</td><td>{{ e.registration?.drawQuota || '未收录' }}</td><td>{{ e.registration?.directQuota || '未收录' }}</td><td>{{ e.registration?.lotteryRate || '未收录' }}</td></tr></tbody></table></div><p class="archive-caption">选择年份查看对应口径说明与来源。</p></section></template>
          <template v-if="tab==='participation'"><section class="archive-panel"><h2>{{ year }} 年参赛与完赛</h2><dl class="archive-facts"><div v-for="f in participationFacts" :key="f.label"><dt>{{ f.label }}</dt><dd>{{ f.value }}</dd></div></dl><p v-if="edition.participation?.note" class="archive-prose">{{ edition.participation.note }}</p></section><section class="archive-panel"><h2>本届成绩</h2><p v-if="!edition.results?.length" class="archive-prose">暂无本届已核验成绩。</p><div v-for="(r,i) in edition.results||[]" :key="i" class="archive-result"><div><strong>{{ r.group }}</strong><span>{{ r.athlete }}</span><small>{{ r.timing || '计时口径见来源' }}</small></div><b>{{ r.time }}</b></div></section></template>
          <template v-if="tab==='gear'"><section class="archive-panel"><h2>{{ year }} 年赛事物品</h2><p class="archive-caption">按本届官方资料记录参赛包、完赛包、服装与奖牌；仅展示已收录的图片和清单。</p><p v-if="!edition.gear?.length" class="archive-prose">本届赛事物品资料尚未核验收录。</p><article v-for="(g,i) in edition.gear||[]" :key="i" class="archive-gear"><span class="archive-kicker">{{ g.category }}</span><h3>{{ g.name || g.category }}</h3><p>{{ g.description }}</p><a v-if="safeUrl(g.imageUrl) && !failedImage('gear-'+i)" class="archive-gear-image" :href="g.imageUrl" target="_blank" rel="noopener noreferrer"><img :src="g.imageUrl" :alt="year+'年'+race.name+' '+(g.name||g.category)" loading="lazy" @error="markImageFailed('gear-'+i)" /><span>查看物品大图 ↗</span></a><p v-if="failedImage('gear-'+i)" class="archive-caption">图片暂时无法显示，可查看物品原文。</p><ul v-if="g.items?.length" class="archive-items"><li v-for="item in g.items" :key="item">{{ item }}</li></ul><a v-if="safeUrl(g.sourceUrl)" class="archive-external" :href="g.sourceUrl" target="_blank" rel="noopener noreferrer">查看物品原文 ↗</a></article></section></template>
          <template v-if="tab==='stories'"><section class="archive-panel"><h2>赛道之外的故事</h2><p class="archive-caption">这里保留有公开出处的赛事掌故与城市记忆。</p><p v-if="!archive.stories?.length" class="archive-prose">赛事故事整理中。</p><article v-for="(s,i) in archive.stories||[]" :key="i" class="archive-editorial"><h3>{{ s.title }}</h3><p>{{ s.body }}</p></article></section></template>
        </template>
        <section v-if="activeSources.length" class="archive-panel archive-sources"><h2>本栏资料来源</h2><a v-for="s in activeSources" :key="s.id" :href="safeUrl(s.url)?s.url:undefined" target="_blank" rel="noopener noreferrer"><span>{{ s.title }}</span><small>{{ s.publisher }}{{ s.publishedAt?' · '+s.publishedAt:'' }}</small><span v-if="safeUrl(s.url)" class="archive-source-action">查看原文 ↗</span></a></section>
        <section v-if="relatedRaces.length" class="archive-panel"><h2>单届赛事与报名信息</h2><router-link v-for="r in relatedRaces" :key="r.id" class="archive-related" :to="'/races/'+r.id"><span><strong>{{ r.name }}</strong><small>{{ r.raceDate }}</small></span><span aria-hidden="true">›</span></router-link></section>
        <p class="archive-caption archive-updated">资料更新 {{ archive.updatedAt || '整理中' }} · 不同年份的资料分别记录</p>
      </div>
    </template>
  </main>
</template>
<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {api} from '../api';
const route=useRoute(),router=useRouter(),race=ref(null),archive=ref(null),relatedRaces=ref([]),years=ref([]),defaultYear=ref(''),year=ref(''),loading=ref(true),error=ref(''),imageFailures=ref([]);
const tabs=[{id:'overview',label:'概览'},{id:'route',label:'赛道'},{id:'registration',label:'报名中签'},{id:'participation',label:'参赛完赛'},{id:'gear',label:'装备收藏'},{id:'stories',label:'赛事故事'}];
const tab=ref(tabs.some(t=>t.id===route.query.tab)?route.query.tab:'overview');let seq=0;
function safeUrl(v){return /^https:\/\/[^\s/@?#]+(?:[/?#][^\s]*)?$/i.test(String(v||'')) || /^\/marathon\/images\/race-archives\/[a-z0-9_/-]+\.(?:png|jpe?g|webp)$/i.test(String(v||''));}
function certification(v){return v?.label?v.label+(v.year?' · '+v.year:''):'待核实';}
const directoryTo=computed(()=>({path:'/race-catalog',query:Object.fromEntries(['q','wa','caa'].filter(key=>route.query[key]).map(key=>[key,route.query[key]]))}));
const editions=computed(()=>[...(archive.value?.editions||[])].sort((a,b)=>Number(b.year)-Number(a.year)));
const edition=computed(()=>editions.value.find(e=>String(e.year)===year.value));
const fromRace=computed(()=>relatedRaces.value.find(r=>String(r.id)===String(route.query.fromRaceId||'')));
const fields=(value,labels)=>labels.map(([key,label])=>({label,value:value?.[key]||'未收录'}));
const registrationFacts=computed(()=>fields(edition.value?.registration,[['opens','报名开始'],['closes','报名截止'],['drawDate','抽签公布'],['fee','报名费用'],['qualification','报名资格'],['applicants','报名人数'],['eligibleApplicants','有效报名'],['lotteryPool','实际抽签人数'],['drawQuota','抽签名额'],['directQuota','直通名额'],['lotteryRate','公布中签率']]));
const participationFacts=computed(()=>fields(edition.value?.participation,[['planned','计划规模'],['starters','实际起跑'],['finishers','完赛人数'],['finishRate','完赛率']]));
const activeSources=computed(()=>{const e=edition.value;let ids=[];if(e){if(tab.value==='overview')ids=[...(e.dateSourceIds||[])];if(tab.value==='route')ids=e.route?.sourceIds||[];if(tab.value==='registration')ids=e.registration?.sourceIds||[];if(tab.value==='participation')ids=[...(e.participation?.sourceIds||[]),...(e.results||[]).flatMap(r=>r.sourceIds||[])];if(tab.value==='gear')ids=(e.gear||[]).flatMap(g=>g.sourceIds||[]);}if(tab.value==='stories')ids=(archive.value?.stories||[]).flatMap(s=>s.sourceIds||[]);return (archive.value?.sources||[]).filter(s=>ids.includes(s.id));});
function updateQuery(){router.replace({query:{...route.query,year:year.value,tab:tab.value}});}
function chooseYear(){imageFailures.value=[];updateQuery();}function setYear(value){year.value=value;chooseYear();}function chooseTab(value){tab.value=value;updateQuery();}
function failedImage(key){return imageFailures.value.includes(year.value+'-'+key);}function markImageFailed(key){imageFailures.value=[...imageFailures.value,year.value+'-'+key];}
async function load(){const request=++seq;loading.value=true;error.value='';race.value=null;archive.value=null;try{const d=await api('/race-catalog/'+encodeURIComponent(String(route.params.id)));if(request!==seq)return;if(!d.race||!d.archive)throw Error('这场赛事尚无已收录档案');race.value=d.race;archive.value=d.archive;relatedRaces.value=d.relatedRaces||[];years.value=(d.years||d.archive.editions.map(e=>String(e.year))).map(String);const linkedYear=String(relatedRaces.value.find(r=>String(r.id)===String(route.query.fromRaceId||''))?.raceDate||'').slice(0,4);const preferred=String(route.query.year||linkedYear);defaultYear.value=String(d.defaultYear||d.latestYear||years.value[0]||'');year.value=years.value.includes(preferred)?preferred:defaultYear.value;imageFailures.value=[];}catch(e){if(request===seq)error.value=e.message||'赛事档案暂时无法加载';}finally{if(request===seq)loading.value=false;}}
watch(()=>route.params.id,load,{immediate:true});
watch(()=>[route.query.year,route.query.tab],([requestedYear,requestedTab])=>{const linkedYear=String(relatedRaces.value.find(r=>String(r.id)===String(route.query.fromRaceId||''))?.raceDate||'').slice(0,4);const preferred=String(requestedYear||linkedYear);year.value=years.value.includes(preferred)?preferred:defaultYear.value;tab.value=tabs.some(t=>t.id===requestedTab)?requestedTab:'overview';imageFailures.value=[];});
onBeforeUnmount(()=>seq++);
</script>
<style src="../race-archive.css"></style>
